package io.lumine.mythic.lib.api.crafting.recipes; import io.lumine.mythic.lib.api.crafting.ingredients.*; import io.lumine.mythic.lib.api.util.Ref; import net.minecraft.item.ItemStack; import java.util.*; public class ShapelessRecipe extends MythicRecipe implements VanillaBookableRecipe { public ShapelessRecipe(String n,ArrayList<MythicRecipeIngredient> i){super(n,i);} public ShapelessRecipe(String n,MythicRecipeIngredient... i){super(n,i);} public void addIngredient(MythicRecipeIngredient i){ingredients.add(i);} public MythicRecipeStation getType(){return MythicRecipeStation.WORKBENCH;} public MythicRecipeInventory matches(MythicRecipeInventory inv,Ref<Integer> amount){ArrayList<ShapelessItem> pool=pool(inv);ArrayList<MythicIngredient> needs=new ArrayList<>();for(MythicRecipeIngredient i:ingredients)needs.add(i.getIngredient());ArrayList<ShapelessItem> result=matches(pool,needs);if(result==null)return null;if(amount!=null)amount.set(1);return inv.clone();} public ArrayList<ShapelessItem> matches(ArrayList<ShapelessItem> items,ArrayList<MythicIngredient> needs){ArrayList<ShapelessItem> work=ShapelessItem.deepCloneList(items);for(MythicIngredient need:needs){ShapelessItem found=null;for(ShapelessItem item:work)if(item.getAmount()>0&&need.matches(item.getStack(),null)){found=item;break;}if(found==null)return null;found.take(1);}for(ShapelessItem item:work)if(item.getAmount()>0)return null;return work;} public ArrayList<ShapelessItem> pool(MythicRecipeInventory inv){ArrayList<ShapelessItem> out=new ArrayList<>();int id=0;for(int y=0;y<inv.getHeight();y++)for(int x=0;x<inv.getWidth();x++){ItemStack s=inv.getItemAt(x,y);if(s!=null&&!s.isEmpty())out.add(new ShapelessItem(id++,s,x,y));}return out;} }
